import java.util.ArrayList;
import java.util.Scanner;

public class sd1 {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int w = s.nextInt();
        int m = s.nextInt();

        ArrayList<Integer> arr = new ArrayList<Integer>();
        int cntr = 0;
        while (m > 0) {
            if (cntr == 40) {
                throw new ArrayIndexOutOfBoundsException(cntr);
            }
            arr.add(m % w);
            m /= w;
            cntr++;
        }
        arr.add(0);

        boolean flag = true;
        for (int i = 0; i < arr.size(); i++) {
            int d = arr.get(i);
            if (d != 0 && d != 1 && d != w && d != w - 1) {
                flag = false;
                break;
            }
            if ((d == w || d == w - 1) && i + 1 < arr.size()) {
                arr.set(i + 1, arr.get(i + 1) + 1);
            }
        }

        System.out.println(flag ? "YES" : "NO");
    }
}
